-- Shift sessions (security.md §2.5 to §2.7). Generated by prisma migrate diff, then hand-written grants and RLS.
-- CreateTable
CREATE TABLE "tenant"."shift_sessions" (
    "id" UUID NOT NULL,
    "estate_id" UUID NOT NULL,
    "user_id" UUID NOT NULL,
    "gate_id" UUID NOT NULL,
    "device_id" TEXT,
    "started_at" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "ended_at" TIMESTAMPTZ(3),
    "handover_note" TEXT,
    "ended_by" UUID,
    "created_at" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,

    CONSTRAINT "shift_sessions_pkey" PRIMARY KEY ("id")
);

-- CreateIndex
CREATE INDEX "shift_sessions_estate_id_gate_id_started_at_idx" ON "tenant"."shift_sessions"("estate_id", "gate_id", "started_at");

-- CreateIndex
CREATE INDEX "shift_sessions_estate_id_user_id_started_at_idx" ON "tenant"."shift_sessions"("estate_id", "user_id", "started_at");


-- Hand-written: grants, row-level security and checks. No DELETE: attendance is a record.
GRANT SELECT, INSERT, UPDATE ON "tenant"."shift_sessions" TO safezone_app;
ALTER TABLE "tenant"."shift_sessions" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "tenant"."shift_sessions" FORCE ROW LEVEL SECURITY;
CREATE POLICY shift_sessions_tenant ON "tenant"."shift_sessions" FOR ALL TO safezone_app
  USING (estate_id = nullif(current_setting('app.estate_id', true), '')::uuid)
  WITH CHECK (estate_id = nullif(current_setting('app.estate_id', true), '')::uuid);
-- One open shift per guard per estate (rule 2, until devices carry their own session).
CREATE UNIQUE INDEX shift_sessions_one_open_per_user ON "tenant"."shift_sessions"(estate_id, user_id)
  WHERE ended_at IS NULL;
ALTER TABLE "tenant"."shift_sessions" ADD CONSTRAINT shift_sessions_end_check
  CHECK (ended_at IS NULL OR (ended_at >= started_at AND handover_note IS NOT NULL));
